// Module 5 — Emerging & Future Technologies
// Bloom's-aligned MCQs. Each topic follows the progression:
// Q1-Q2 Remember · Q3-Q4 Understand · Q5-Q7 Apply · Q8 Analyze · Q9 Evaluate · Q10 Create
// All options are roughly equal length (distractors may be longer, never shorter than the correct answer).

import type { Question } from "./module1-mcq";

export const mcqData: Record<number, Question[]> = {
  // ─── Topic 1: Artificial Intelligence (Narrow, General, Super) ───
  1: [
    { q: "Which of the following is the correct definition of Artificial Intelligence?", opts: ["A physical robot with a metal body that walks around and does chores", "Machines simulating intelligent human-like behaviour in software or hardware", "Any computer connected to the internet that runs modern fast software and most modern teams have moved to exactly this way of doing things", "A new kind of microchip that replaces older central processing units"], ans: 1, why: "AI means perceiving, reasoning, learning, and acting in ways that look intelligent — it is defined by the behaviour, not by shape (robot) or hardware. A spam filter is AI; a toaster with a plug is not. Software alone can absolutely count as AI.", bloom: "remember" },
    { q: "What are the three commonly taught levels of AI, from weakest to strongest?", opts: ["Narrow AI (one task), General AI (any task), Super AI (beyond humans)", "Basic AI, Medium AI, Expert AI — the levels that every textbook lists first", "Phone AI, Laptop AI, Cloud AI — the three device-based types of AI systems", "Old AI, Current AI, Future AI — the three historical generations of AI tools"], ans: 0, why: "Narrow AI handles ONE task (Siri, Netflix recommender). General AI would match a human across ANY task — it does not exist yet. Super AI would exceed humans everywhere — purely theoretical. The other options are made up.", bloom: "remember" },
    { q: "Why is today's AI still classified as \"Narrow\" even when it beats humans at specific tasks like chess or image recognition?", opts: ["Because it is weak at everything and cannot really compete with skilled human experts", "Because it uses less computer memory than a normal laptop uses each day", "Because each system is specialised for one task and cannot transfer skills", "Because it is newer than older rule-based computer programs from before"], ans: 2, why: "Narrow AI is specialised: a chess AI masters chess but can't diagnose illness or drive a car. General AI would be one system handling ANY task a human can. Narrow does not mean weak — it means task-specific.", bloom: "understand" },
    { q: "What is the main difference between Narrow AI and General AI?", opts: ["Narrow AI is free software and General AI is paid enterprise subscription software", "General AI runs on faster chips than the ones used for Narrow AI systems", "Narrow AI does one task well; General AI would match humans across ALL tasks", "Narrow AI was built before 2020 and General AI was built after the year 2020"], ans: 2, why: "The difference is BREADTH, not speed, cost, or date. Narrow AI = task-specific expert (translation, images, spam). General AI would flexibly handle any cognitive task a human can. General AI does not yet exist.", bloom: "understand" },
    { q: "Netflix recommending shows, Siri answering questions, and Yandex Taxi predicting arrival time — these are all examples of what?", opts: ["General AI because they handle many different kinds of everyday user requests", "Narrow AI because each is designed for one specific task only", "Super AI because they perform faster than any human expert could manage", "Not AI at all — these are only regular computer programs with simple rules"], ans: 1, why: "Each is designed for one specific task and cannot transfer to another. Netflix can't drive a car; Siri can't diagnose cancer. That is the Narrow AI signature — useful, narrow, and everywhere.", bloom: "apply" },
    { q: "A student says ChatGPT is \"General AI\" because it can answer questions on many topics. Apply what you know — is this correct?", opts: ["Yes, it clearly qualifies as General AI because it talks about every subject fluently", "Yes, because answering multiple topics is the exact official definition of General AI", "No — it is still Narrow AI (text prediction), just trained on very broad text data", "No, because General AI must be a physical robot with arms, legs, and moving sensors"], ans: 2, why: "ChatGPT is a text-prediction system trained on lots of text. \"Broad topics\" is not the same as General AI. It cannot plan long-term, act in the physical world, or truly understand — it predicts likely next words. Breadth of topic is not breadth of capability.", bloom: "apply" },
    { q: "A Tashkent startup claims their \"General AI\" assistant can write emails, book flights, and do accounting. Apply what you know — what is probably really happening?", opts: ["It is true General AI — the technology has finally arrived in Uzbekistan markets", "It is Super AI, which is why it seems to handle so many different tasks so well", "It is several Narrow AI tools bundled together and marketed as one product", "It is a trick — there is no AI involved at all, just humans answering behind it"], ans: 2, why: "It is likely several Narrow AI tools (or one language model calling different tools) dressed up as one general system. Marketing uses \"General AI\" loosely; the academic meaning (human-level across ALL tasks) does not exist yet.", bloom: "apply" },
    { q: "A hospital claims their AI diagnoses cancer better than doctors on test data. Analyse the trust gap between \"high test accuracy\" and \"safe to deploy in real care.\"", opts: ["There are real deployment risks beyond accuracy: edge cases, explanation, accountability", "Accuracy on test data is literally all that matters once the number is published", "The AI should fully replace all doctors immediately to save hospital costs fast", "High accuracy on a benchmark is always faked and never reflects real model ability and most modern teams have moved to exactly this way of doing things"], ans: 0, why: "Test data may not reflect real edge cases, AI can't explain its reasoning to a patient, mistakes need an accountable party, and rare conditions are often under-represented in training. High accuracy is necessary but not sufficient for deployment.", bloom: "analyze" },
    { q: "Evaluate the claim: \"Since AI is getting smarter, universities should teach less and just let AI tutors handle students directly.\"", opts: ["Correct — AI has already proven it can replace teachers across every subject area", "Correct — teachers are obsolete because AI tutors are always available day and night and most modern teams have moved to exactly this way of doing things", "Incorrect — AI tutors do not work at all and never will in any educational setting", "Flawed — AI fits drill and practice, but humans fit judgment, ethics, and collaboration"], ans: 3, why: "AI tutors CAN personalise drill and explanations. But universities teach critical thinking, collaboration, ethics, and research — areas where current AI hallucinates confidently. Better framing: AI for practice plus humans for judgment, not substitution.", bloom: "evaluate" },
    { q: "Design a responsible use of AI in a Tashkent university classroom that supports learning without enabling cheating.", opts: ["Ban every kind of AI tool on campus and punish any student caught using it", "Allow AI as a disclosed tool for brainstorming, with oral checks on submitted work", "Require every student to use AI on every single assignment with no exceptions at all", "Ignore the whole issue and hope that students decide for themselves what is fair use"], ans: 1, why: "Students use AI for brainstorming, concept explanation, practice quizzes, and language polishing — then disclose it in an appendix. Assessments include in-class oral checks AI can't help with. An AI-literacy class teaches when to use and when to avoid. Separates AI-as-tool (good) from AI-as-replacement-for-thinking (cheating).", bloom: "create" },
  ],

  // ─── Topic 2: Machine Learning (Supervised, Unsupervised, Reinforcement) ───
  2: [
    { q: "Which statement correctly distinguishes the three main types of Machine Learning?", opts: ["They are synonyms — different names for exactly the same computer-learning method", "ML does not really have types; it is one single algorithm used in every situation", "Only Supervised learning is real; the others are just marketing words used by companies and most modern teams have moved to exactly this way of doing things", "Supervised uses labelled data, Unsupervised finds patterns, Reinforcement learns by reward"], ans: 3, why: "Supervised learns from labelled examples; Unsupervised finds patterns in unlabelled data; Reinforcement learns through trial, reward, and penalty. Each suits different data and goals.", bloom: "remember" },
    { q: "What does it mean for Machine Learning data to be \"labelled\"?", opts: ["Each training example comes with the correct answer attached so the model can learn", "The data file has a printed paper label stuck on top of the computer hard drive", "The data is written in a special computer language not used by any other program and most modern teams have moved to exactly this way of doing things", "The data has been officially approved by a government labelling agency for use"], ans: 0, why: "A label is the correct answer attached to each example — \"this email is spam,\" \"this photo is a cat.\" The model learns to match inputs to labels. Labelling often requires human effort, which is why labelled data is expensive and why unsupervised learning matters.", bloom: "remember" },
    { q: "Why does more data usually help a machine learning model — but only up to a point?", opts: ["More examples = better chance to learn real patterns, with diminishing returns over time", "The data secretly contains the hidden right answers that the model just memorises directly", "More data always helps with absolutely no upper limit, regardless of quality or source", "More data always hurts a model because it becomes confused and forgets its earlier training"], ans: 0, why: "Models learn patterns by seeing examples. More examples = more chances to separate signal from noise. But after enough data the returns diminish, and poor-quality data hurts more than it helps. It is a curve, not a straight line upward.", bloom: "understand" },
    { q: "What does \"overfitting\" mean in Machine Learning?", opts: ["The computer gets physically too hot when training on very large datasets for long periods", "The model memorises training data specifics instead of learning patterns that generalise", "The dataset is larger than the hard drive and the computer runs out of storage space", "The model is simply too big for the screen and cannot be displayed to the user at once"], ans: 1, why: "Overfitting = the model memorises the exact training examples instead of learning generalisable patterns. Sign: high training accuracy but low test accuracy on new data. Fix: more diverse data, simpler model, regularisation, or cross-validation.", bloom: "understand" },
    { q: "Gmail's spam filter uses data labelled by users as \"spam\" or \"not spam\" to improve. Which ML type is this?", opts: ["Unsupervised learning because Gmail is just sorting emails into clusters on its own", "Reinforcement learning because Gmail is being rewarded for making correct spam decisions", "Supervised learning because each example comes with a correct spam / not-spam label", "None of the three types — Gmail uses hand-written rules that programmers code by hand"], ans: 2, why: "Labels (spam / not-spam) teach the model the correct classification. When each training example has a known right answer, that is Supervised. Users flagging emails is the labelling step that keeps the filter improving.", bloom: "apply" },
    { q: "An Uzbek retailer wants to group customers into segments WITHOUT deciding the categories in advance. Which ML type fits?", opts: ["Supervised learning because the retailer wants the computer to give very accurate predictions", "Unsupervised learning because the model finds natural clusters in the data on its own", "Reinforcement learning because the retailer rewards the model for each good customer group", "No ML type at all — the retailer should just sort the customers by age and by income level"], ans: 1, why: "The retailer has raw data but no predefined \"correct\" groups. The model finds natural clusters on its own — that is Unsupervised, specifically clustering. No labels needed, just patterns in the data.", bloom: "apply" },
    { q: "A game studio wants to train an AI to play a football game by letting it try, reward goals, and penalise own-goals. Which ML type?", opts: ["Supervised learning because every possible move has one single official correct answer", "Unsupervised learning because the AI is just exploring different kinds of football strategies", "Reinforcement learning because the AI learns from trial, reward, and penalty over many games", "None of the above — games cannot really be learned by any type of machine learning system"], ans: 2, why: "Learn by trial + reward + penalty = Reinforcement Learning. The AI plays thousands of games, receiving positive reward for goals and negative for mistakes, slowly improving a policy. Famous examples: AlphaGo, self-driving simulators, robot locomotion.", bloom: "apply" },
    { q: "A facial recognition model hits 95% on training data but only 60% on new faces it has never seen. Analyse what is going wrong.", opts: ["Overfitting — the model memorised training-set specifics instead of learning general features", "Test data is just harder than training data, so this performance gap is always expected", "The model is actually perfect and 60% is the best possible score any model could achieve and most modern teams have moved to exactly this way of doing things", "This is unavoidable — every machine learning model always behaves in exactly this way"], ans: 0, why: "High training accuracy + low test accuracy is the textbook overfitting signature. The model memorised training-set specifics rather than learning generalisable features. Fixes: more diverse training data, regularisation, simpler model, cross-validation.", bloom: "analyze" },
    { q: "A manager argues: \"We should always prefer supervised learning — labels make results more accurate.\" Evaluate this claim.", opts: ["Correct — supervised always wins because labels always beat any kind of unlabelled data analysis and most modern teams have moved to exactly this way of doing things", "All three ML methods are identical in result, so the choice of method never actually matters", "Correct — labels are free and easy, so there is no reason ever to choose another approach", "Flawed — labels are expensive or unavailable, and many problems fit unsupervised or reinforcement better"], ans: 3, why: "Supervised needs labels, which cost human annotation time or may not exist. Customer segmentation, anomaly detection, and exploring unknown structure fit unsupervised. Sequential-decision problems (games, robotics) fit reinforcement. Match the method to the problem, not vice versa.", bloom: "evaluate" },
    { q: "Design an ML approach for an Uzbek bank that wants to detect credit-card fraud. What type(s), what data, what challenge?", opts: ["No ML is needed — the bank should just block every single suspicious transaction every time and most modern teams have moved to exactly this way of doing things", "Only unsupervised — ignore historical fraud examples and rely purely on anomaly detection", "Hybrid supervised + unsupervised with human review, using transaction history and behavioural data", "Block every card transaction over a fixed amount and never use any machine learning at all"], ans: 2, why: "Supervised catches known fraud patterns (labelled historical cases). Unsupervised spots novel patterns (outliers vs. a user's normal behaviour). Data: amount, location, time, merchant, device. Challenges: very imbalanced classes (fraud is rare), evolving attackers, false-positive cost for real customers. Human review before blocking.", bloom: "create" },
  ],

  // ─── Topic 3: Data Analytics (Descriptive, Diagnostic, Predictive, Prescriptive) ───
  3: [
    { q: "Which ordering correctly ranks the four types of analytics from simplest to most advanced?", opts: ["Prescriptive → Predictive → Diagnostic → Descriptive — the order most textbooks show first", "Diagnostic → Descriptive → Predictive → Prescriptive — the historical order of invention", "Descriptive → Diagnostic → Predictive → Prescriptive — what, why, what next, what to do", "Predictive → Descriptive → Prescriptive → Diagnostic — simplest forecasting model first"], ans: 2, why: "The canonical ladder: Descriptive (what happened) → Diagnostic (why) → Predictive (what will happen) → Prescriptive (what should we do). Each step builds on the one before and adds more capability and more responsibility.", bloom: "remember" },
    { q: "What does Descriptive Analytics answer?", opts: ["What happened in the past — summarising past data using charts, totals, and averages", "Why something happened — digging into causes behind a change in sales or costs", "What will happen next — using past data to forecast future events or outcomes", "What action should be taken — recommending a specific decision based on a forecast and most modern teams have moved to exactly this way of doing things"], ans: 0, why: "Descriptive = \"what happened.\" It summarises past data into reports, dashboards, totals, averages. A monthly sales report is descriptive. It is the foundation every other type of analytics builds on.", bloom: "remember" },
    { q: "Why is Prescriptive Analytics considered the most advanced of the four types?", opts: ["It uses the fastest and most expensive cloud computers available to any business today", "It doesn't just describe or predict — it RECOMMENDS specific actions to take", "It was invented most recently and therefore it is the newest kind of analytics", "It doesn't actually exist in the real world and is only a theoretical idea from textbooks"], ans: 1, why: "It doesn't just describe, explain, or predict — it recommends specific actions, combining analysis with decision logic and often AI. Acting on recommendations carries higher stakes than reporting numbers. Each step adds capability; prescriptive is \"here's what to do.\"", bloom: "understand" },
    { q: "Which analytics type answers the question \"Why did it happen?\"", opts: ["Descriptive analytics, because it summarises past data into charts and monthly reports", "Diagnostic analytics, because it investigates root causes behind a change in outcome", "Predictive analytics, because it uses past data to forecast what will happen next", "Prescriptive analytics, because it tells decision-makers what specific action they should take"], ans: 1, why: "\"Why\" = Diagnostic analytics. It digs into causes behind what Descriptive describes. Example: sales dropped 20% (Descriptive) because of a rainy season that closed outdoor markets (Diagnostic). Without Diagnostic, fixes are guesses.", bloom: "understand" },
    { q: "A monthly report showing \"Q1 revenue was $2.1M, down 8% from Q4\" is which type of analytics?", opts: ["Descriptive — it simply states what happened in the past without explaining the cause", "Predictive — it uses past revenue data to forecast the revenue level for the coming quarter", "Prescriptive — it recommends a specific action for the company to take based on this data", "Diagnostic — it explains exactly why revenue fell by 8% compared to the previous quarter"], ans: 0, why: "It describes what happened without asking why, forecasting, or recommending. Past facts only = Descriptive. It is the foundation layer — every other analytics type builds on top of Descriptive reports.", bloom: "apply" },
    { q: "A retailer's AI says: \"Launch a 15% discount on bedroom furniture starting April 1 to clear inventory before May 1.\" Which type?", opts: ["Descriptive, because it describes the current inventory situation for bedroom furniture stock", "Predictive, because it forecasts that furniture inventory will remain very high into May", "Prescriptive, because it recommends a specific action with timing, scope, and magnitude", "Diagnostic, because it explains exactly why the bedroom furniture inventory got too high"], ans: 2, why: "It recommends a specific action, with timing and magnitude. Predictive would stop at \"inventory will be too high by May.\" Prescriptive closes the loop by saying what to do about it.", bloom: "apply" },
    { q: "A university wants to flag first-year students at risk of dropping out BEFORE they actually drop out. Which analytics type fits?", opts: ["Descriptive, because the university needs to summarise current dropout numbers and trends", "Diagnostic, because the university needs to explain why past students have dropped out", "Predictive, because the university wants to forecast which current students are at risk", "Prescriptive, because the university wants to recommend a retention action for each student"], ans: 2, why: "Forecasting future outcomes (drop-out risk) based on patterns in historical data = Predictive. Next step would be Prescriptive: a recommendation (tutoring, financial aid, mentoring) for each flagged student.", bloom: "apply" },
    { q: "A company uses descriptive reports saying \"sales dropped 20%\" but never investigates why. Analyse the consequences of skipping Diagnostic Analytics.", opts: ["They know the fact but not the cause, so any fix is a guess and the drop may repeat", "There are absolutely no real consequences since the company still knows the sales number", "Diagnostic analytics is optional and most successful companies never really use it anyway", "Descriptive alone is enough because the numbers will eventually explain themselves over time"], ans: 0, why: "Without Diagnostic, they can't target fixes — any action is a guess. Next quarter the drop may repeat because the cause was never addressed. Descriptive without Diagnostic is a thermometer without a diagnosis: you know you are sick, not why.", bloom: "analyze" },
    { q: "A startup debates whether to invest in Predictive Analytics or keep doing only Descriptive reports. Evaluate the decision.", opts: ["Always skip Predictive — it costs too much and never pays back for any small startup", "Always use Predictive for everything, even for one-off decisions and low-value choices", "Both approaches are equally useless for any startup regardless of industry or decision type and most modern teams have moved to exactly this way of doing things", "It depends on decision stakes — Predictive pays off when forecasts drive recurring real decisions"], ans: 3, why: "If they make recurring decisions (inventory, staffing, ad spend) whose outcome depends on future demand, Predictive pays off fast. For one-off or low-stakes decisions, Descriptive is fine. Invest in Predictive when forecasts drive real decisions, not for its own sake.", bloom: "evaluate" },
    { q: "Design a 4-step analytics plan for a Tashkent university that wants to improve graduation rates (currently 70%).", opts: ["Just hope for the best and trust that graduation rates will rise on their own next year", "Describe current rates → diagnose dropout causes → predict at-risk students → prescribe interventions", "Cancel the university programme entirely and stop admitting new first-year students altogether and most modern teams have moved to exactly this way of doing things", "Only use descriptive reports — no need for diagnosis, prediction, or intervention design steps"], ans: 1, why: "1. Descriptive: current graduation rate per department, cohort. 2. Diagnostic: which factors correlate with drop-outs — grades, attendance, money, first-year results. 3. Predictive: flag at-risk students each semester using those factors. 4. Prescriptive: targeted interventions (tutoring, financial counselling, mentoring). Measure against baseline.", bloom: "create" },
  ],

  // ─── Topic 4: Cloud Computing (simple, school-level) ───
  // Rewritten for 17-year-old first-time ICT students. No IaaS/PaaS/SaaS,
  // no deployment models — just "what is cloud, why use it, how it helps."
  // Bloom's: Q1-Q2 Remember · Q3-Q4 Understand · Q5-Q7 Apply · Q8 Analyze ·
  // Q9 Evaluate · Q10 Create. Correct answer is never the longest option.
  4: [
    { q: "What is cloud computing, in simple words?", opts: ["Saving your files and running programs on big computers on the internet, not only on your own device", "A special weather-tracking program that predicts rain, snow, and cloud movement using satellite data every hour", "A type of faster Wi-Fi connection that only works outside when there are real clouds visible in the sky", "A new kind of laptop battery that was invented to last much longer than older models on the market today"], ans: 0, why: "Cloud computing means your files and apps live on powerful computers on the internet (called servers), not only on your phone or laptop. You reach them through the internet from any device. The 'cloud' has nothing to do with weather — it's just a word for 'on the internet'.", bloom: "remember" },
    { q: "Which of these is an example of using the cloud in daily life?", opts: ["Saving photos to Google Photos or iCloud so you can open them from your phone and laptop", "Writing a note using a pen and paper in your school notebook during a lesson in the classroom", "Printing your homework on a home printer before going to school the next morning", "Copying a file from one folder to another folder on the same laptop's hard drive at home"], ans: 0, why: "Google Photos and iCloud save your photos on Google's or Apple's cloud computers. That's why you can open the same photo from your phone AND your laptop. A paper note, a print-out, and a folder-to-folder copy all stay on ONE device — that is not cloud.", bloom: "remember" },
    { q: "Why can you open the same Gmail inbox from your phone, your laptop, AND a friend's computer?", opts: ["Your emails are saved on Google's cloud servers, so any device with your login can open them", "Your phone secretly sends the emails to your laptop through Bluetooth whenever the phone is charging", "Gmail makes a hidden copy on every device you have ever used to sign in to the email service", "Your SIM card carries the emails wherever you go and shares them with any device you touch later"], ans: 0, why: "Gmail is a cloud app. Your emails sit on Google's big computers (servers) on the internet. Any device that signs in with your password sees the SAME inbox, because they are all looking at the same cloud copy. Bluetooth, SIM cards, and hidden device copies are not how it works.", bloom: "understand" },
    { q: "What is the main difference between saving a file in the cloud and saving it only on your laptop?", opts: ["Cloud files can be opened from many devices; laptop-only files live on one device and can be lost", "Cloud files are always pictures while laptop files are always text documents saved in English", "Cloud files are always free and laptop files always cost money to save for your school assignments", "Cloud files work only in the morning and laptop files work only when it is dark outside at night"], ans: 0, why: "A file saved only on your laptop stays on that one machine. If the laptop breaks or is lost, the file goes with it. A cloud file is kept safely on the internet — you can open it from any device, and it's still there even if your laptop dies. That is the main difference.", bloom: "understand" },
    { q: "A student loses her phone on the bus with 3 years of family photos on it. What would have kept her photos safe?", opts: ["Turning on cloud backup (Google Photos or iCloud) so photos are also saved on the internet", "Installing an anti-virus app on the phone to stop the photos from getting infected by viruses", "Keeping the phone in a hard plastic case so the photos inside would not get scratched on the bus", "Setting a strong screen-lock password so no one could open the phone after finding it on the seat"], ans: 0, why: "Anti-virus protects against malware, a case protects the hardware, a password protects privacy — none of them bring back a lost phone. Cloud backup means a second copy of every photo is saved on Google's or Apple's servers on the internet. New phone + sign in + all photos are back.", bloom: "apply" },
    { q: "You start writing a school project at home on your laptop. Tomorrow you need to finish it from your cousin's computer. What is the easiest way?", opts: ["Save it to Google Docs or OneDrive, then sign in on your cousin's computer and keep working", "Email the file to yourself again and again after every sentence you finish typing on the laptop", "Print the whole project, carry the papers, and retype everything from the start on the other computer", "Memorise the full project in your head and type it again from memory on your cousin's computer"], ans: 0, why: "Cloud apps like Google Docs, OneDrive, and Dropbox save your work on the internet as you type. Sign in from ANY computer and continue exactly where you stopped — no emailing, no retyping, no printing. This is one of the biggest everyday wins of the cloud for students.", bloom: "apply" },
    { q: "A class of 40 students wants to work on ONE shared document together at the same time. What is the best choice?", opts: ["A cloud document like Google Docs, where all 40 students can type in the same file together", "One Word file shared through a USB stick that is passed around from desk to desk all period long", "A paper document that the students write on one after another during the whole class period", "40 separate copies on 40 laptops, which the teacher will later combine into one file by hand"], ans: 0, why: "Google Docs is a cloud app. Many people can open the SAME file at the same time and see each other typing live. A USB stick works for one person at a time; paper and 40 separate copies waste time. Real-time shared editing is only possible because the file lives on the cloud.", bloom: "apply" },
    { q: "What is one real limitation of cloud storage that you should always remember?", opts: ["If you have no internet connection, you cannot reach your cloud files until the internet works again", "Cloud files become smaller every week and slowly disappear if you do not open them often enough", "Cloud files only work on Apple devices — they cannot be opened on any Windows or Android phone", "Cloud files always take many hours to open even on a very fast and reliable internet connection"], ans: 0, why: "The cloud needs internet — no Wi-Fi or mobile data means no access to your files. Files do NOT shrink on their own, they work on every device (Android, Windows, Apple, Linux), and modern clouds open files in seconds. But internet is a real requirement: always keep an offline copy of anything critical.", bloom: "analyze" },
    { q: "Your friend says: \"Cloud is useless — you should save everything only on your own laptop, because then nobody else can ever see it.\" Evaluate this.", opts: ["Not fully right — the cloud gives backup and easy sharing; a strong password keeps it private enough", "Fully correct — the cloud is a scam and nobody who cares about their files should ever use any cloud app", "Fully wrong — laptops are obsolete and every person should delete every file from every laptop they own", "Partly right — but only because cloud apps usually delete your files by themselves after a week or so"], ans: 0, why: "A laptop-only file is private BUT risky — if the laptop breaks, the file is gone. The cloud is also private IF you use a strong password + 2-step sign-in. Best answer = both: keep important files on the cloud for backup and sharing, and keep a second copy on your device for offline work. Neither option is automatically 'always best'.", bloom: "evaluate" },
    { q: "Design a simple plan for a student so that school notes and projects are NEVER lost, even if the laptop breaks.", opts: ["Save every file to Google Drive (or OneDrive), turn on phone photo backup, and keep one copy on the laptop", "Save every file only on the laptop and hope that the laptop will never break for the next four full years", "Print every single note and project and keep all the papers stacked on the student's desk at home only", "Send every single note in a Telegram message to five different friends and ask them all to save it for you"], ans: 0, why: "The safe plan is 'cloud + device': main copy on the cloud (Google Drive or OneDrive) so it's reachable anywhere AND safe if the laptop dies; a second copy on the laptop for offline work; phone photos auto-backed to the cloud. Printing wastes paper and is hard to search. Asking friends is not secure and not reliable.", bloom: "create" },
  ],

  // ─── Topic 5: Blockchain ───
  5: [
    { q: "Which statement correctly describes what a blockchain actually is?", opts: ["A new kind of cryptocurrency that competes directly with Bitcoin and all other digital coins", "A decentralised, immutable ledger of linked blocks stored across many independent computers", "A cloud storage service where companies upload their photos, videos, and work documents", "A programming language used mostly to build modern web and mobile application front-ends"], ans: 1, why: "Transactions are recorded in linked blocks across many computers; once written, entries are practically immutable. Blockchain is the underlying data structure and distribution pattern. Bitcoin is ONE cryptocurrency built on a blockchain, not blockchain itself.", bloom: "remember" },
    { q: "What does it mean for a blockchain to be \"decentralised\"?", opts: ["No single authority controls it — many computers each hold a copy and validate the ledger", "It is stored in the physical centre of a building where everyone can always easily see it", "It works only in countries that have officially decentralised their national banking system", "It was designed and built in the exact centre of the earth — the most secure location of all"], ans: 0, why: "Decentralised = no single company or government controls the ledger. Many computers each keep a copy and agree via consensus rules. This is what makes blockchain resistant to any single point of failure or control — and also what makes it slow and hard to update.", bloom: "remember" },
    { q: "Why is a blockchain considered \"immutable\" in practice, even though every entry could theoretically be rewritten?", opts: ["The hash-chain cascade makes edits computationally and economically infeasible at any scale", "A single company refuses to let anyone edit it, and enforces this with its own legal team", "Governments have passed laws that legally prevent anyone from ever changing blockchain data", "The blockchain files are stored on special locked hard drives that no one can physically access"], ans: 0, why: "Each block stores a cryptographic hash of the previous block. Changing block #500 changes its hash, invalidating block #501's reference, then #502's, and so on. To rewrite one block, an attacker must rewrite every later block AND outpower the network — infeasible at scale.", bloom: "understand" },
    { q: "What is a cryptocurrency, in one sentence?", opts: ["Any kind of money held inside a mobile phone e-wallet run by a government banking authority", "A digital currency secured by cryptography and recorded on a blockchain instead of a bank ledger", "The official national currency of a country that has a fully digital economic system in place and most modern teams have moved to exactly this way of doing things", "A secret form of physical cash printed on paper but used only for online digital purchases"], ans: 1, why: "A cryptocurrency is digital money secured by cryptography and recorded on a blockchain rather than in a bank's ledger. Bitcoin and Ether are examples. Not the same as blockchain itself — blockchain is the underlying technology; cryptocurrency is one application of it.", bloom: "understand" },
    { q: "A global supply chain uses blockchain to track coffee from farm to cup. Which property of blockchain makes this valuable?", opts: ["Speed, because blockchain is the fastest way to record transactions in the entire modern world", "Low cost, because blockchain runs for free without using any electricity or computer processing", "Immutable audit trail — every handoff is recorded and cannot be retroactively altered later on", "Blockchain is not actually useful for supply chains — this is only marketing with no real benefit"], ans: 2, why: "Every handoff (farmer → processor → shipper → roaster → store) is recorded and can't be retroactively altered. Consumers can trace a cup back to its origin; disputes have a tamper-resistant record. Provenance tracking + dispute resolution depend on an unchangeable record.", bloom: "apply" },
    { q: "A real estate platform claims blockchain means \"home ownership records can never be lost or forged.\" Is this the whole story?", opts: ["Yes — blockchain is magic and handles every single part of the property ownership process", "Only for Bitcoin-style cryptocurrency records; it is not usable for property registration purposes and most modern teams have moved to exactly this way of doing things", "No, blockchain is always useless and never adds any real value to any real-world process", "Partly — the chain is tamper-resistant, but off-chain data entry and legal title remain human problems"], ans: 3, why: "The real benefit is immutability + distribution (many independent copies). But blockchain doesn't solve the \"off-chain\" problem: someone still has to correctly enter who owns the home, and legal title still flows through courts. Blockchain secures the record; it does not replace institutions or verify reality.", bloom: "apply" },
    { q: "A student wants to send a small payment to a friend abroad with no bank involvement. Apply what you know — which cloud/finance tech fits?", opts: ["Traditional wire transfer — fast, cheap, and available to every customer in every single country", "Cryptocurrency on a blockchain — peer-to-peer value transfer without a traditional bank as middleman", "SaaS cloud accounting software — the right tool for instantly moving money between individuals abroad", "Nothing fits — it is actually impossible to move money across borders without a regular bank today"], ans: 1, why: "Cryptocurrency on a blockchain lets people send value directly to each other without a bank. Fees and speed vary by network. Risks remain: price volatility, legal restrictions in some countries (including Uzbek crypto rules), and scam platforms. But the underlying capability is real.", bloom: "apply" },
    { q: "A country proposes blockchain-based voting, arguing it will be \"fraud-proof.\" Analyse the real-world limits.", opts: ["Blockchain-based voting is a perfect solution and fixes every kind of democratic election problem", "Authentication, privacy, coercion, and client software bugs all sit outside the blockchain itself", "Blockchain is always fully fraud-proof — any claim of election fraud is automatically impossible", "Only paper-based voting ever works — no digital system of any kind should ever be used instead"], ans: 1, why: "Limits: (1) Voter authentication (who is really at the keyboard?) is outside the chain. (2) Private ballot + public ledger are in tension. (3) 51% attacks on small chains are real. (4) Coercion at home can't be prevented. (5) Client software bugs can break integrity. \"Immutable record\" ≠ \"correct record.\"", bloom: "analyze" },
    { q: "A founder pitches \"a blockchain social network where your posts can never be deleted.\" Evaluate the idea.", opts: ["Brilliant, because immutability always benefits users across every possible social-network scenario and most modern teams have moved to exactly this way of doing things", "Technically impossible, because blockchains cannot store any kind of text, image, or video content", "Every startup should adopt blockchain storage, because it always improves every social product", "Flawed — immutability becomes a liability for moderation, illegal content, privacy law, and storage cost"], ans: 3, why: "(1) Moderation becomes impossible — illegal or harmful posts stay forever. (2) Privacy laws like GDPR's right-to-deletion directly conflict. (3) Permanent media storage costs are high. (4) The \"censorship-resistant\" feature users want is a compliance nightmare for operators. Immutability is sometimes the bug, not the feature.", bloom: "evaluate" },
    { q: "Design a legitimate, high-value blockchain use case for a small country's government. Why blockchain specifically, vs. a regular database?", opts: ["Blockchain everything — put the entire government onto a single national blockchain for all records and most modern teams have moved to exactly this way of doing things", "A tamper-evident national property registry — multiple departments read, no single authority rewrites", "A social media platform for government officials to post updates about their own daily work", "Voting in national elections — the single most famous and most successful use case for blockchain"], ans: 1, why: "Property registry: (a) records must be tamper-evident across political transitions, (b) multiple departments need read access without a central bottleneck, (c) citizens benefit from transparent provenance during disputes. Immutability + distribution beats a central DB that any single authority could rewrite. Designing a blockchain use case = proving the problem needs immutability + distribution.", bloom: "create" },
  ],

  // ─── Topic 6: Virtual Reality ───
  6: [
    { q: "Which statement correctly defines Virtual Reality (VR)?", opts: ["A phone filter that adds funny hats and animal ears to a user's face on a mobile screen", "A fully computer-generated environment that replaces reality, viewed through a headset", "Any 3D video game that runs on a regular flat monitor in the user's home living room", "A technology that overlays digital objects onto the real world using a clear pair of glasses"], ans: 1, why: "VR = complete replacement of reality, experienced through a headset that blocks out the real world. Option 4 actually describes AR (which overlays). Option 3 is 3D graphics (not immersive). Option 1 is a filter, not VR.", bloom: "remember" },
    { q: "What hardware is most commonly used to experience VR today?", opts: ["A head-mounted display (VR headset) such as Meta Quest that blocks the real world from view", "A smartphone without any extra accessory, held in the user's hand at normal arm's length away", "A regular flat monitor with a standard mouse and keyboard on an ordinary home office desk", "A smart TV running a normal 3D movie with no additional controller, sensor, or headset"], ans: 0, why: "A VR headset (Meta Quest, PlayStation VR, HTC Vive) with stereoscopic displays and head tracking is standard. A phone alone gives at most 3D video but not true immersion or head tracking. Headsets with hand controllers are the full VR experience.", bloom: "remember" },
    { q: "Why does VR feel more \"present\" than watching a 3D movie, even if both show similar content?", opts: ["VR has better pixels than 3D movies, and that higher pixel count is what creates the feeling", "Head tracking makes the scene respond in real time to your motion — you feel you're IN it", "Movies don't use 3D graphics at all, while VR is the only system that uses real 3D graphics", "They feel exactly identical — the immersion is the same and there is no measurable difference"], ans: 1, why: "VR tracks your head and often hands in real time, so the scene responds to your motion. Combined with stereoscopic depth, spatial audio, and a blocked-out real world, the brain accepts the scene as a place you are IN rather than a show you are WATCHING. 3D movies lack that motion-response loop.", bloom: "understand" },
    { q: "What is the main weakness of VR compared to AR for everyday tasks like navigation or shopping?", opts: ["VR headsets cost more money than most AR devices currently on the global consumer market", "VR fully blocks the real world, making it impractical for tasks tied to real locations and objects", "VR has worse graphics than AR and gives a lower-quality image for most real users most of the time", "VR only works indoors, while AR works both indoors and outdoors across every possible location"], ans: 1, why: "VR blocks reality — great for full immersion (games, training) but impractical when the task depends on the real environment. You can't walk through Tashkent with a VR headset on. AR overlays onto reality, keeping you aware. Each fits different jobs.", bloom: "understand" },
    { q: "A medical school wants to teach emergency surgery procedures safely. Why does VR fit this need?", opts: ["VR headsets are cheaper than any other kind of professional medical training equipment available", "Immersive spatial practice transfers to real surgical skill better than a flat-screen tutorial does", "Flat-screen tutorials have always been better than VR for every possible medical training situation", "VR does not help in medical training — doctors learn only from textbooks and live patient cases"], ans: 1, why: "In VR, students stand at a simulated operating table, see the patient from natural angles, and use tracked controllers as instruments. Muscle memory + spatial context transfers to real procedures in ways a flat tutorial can't. Medical training is one of VR's clearest genuine value-adds.", bloom: "apply" },
    { q: "A Tashkent real estate agent wants to show 5 homes to out-of-town buyers in 30 minutes. How does VR help, and what is the limit?", opts: ["VR fully replaces every physical visit and makes the real house tour completely unnecessary", "VR works perfectly with zero drawbacks, so in-person visits should be cancelled in every case", "VR is great for pre-screening homes to a shortlist, but not for the final purchase decision", "VR is totally useless for real estate and no Tashkent agent would ever consider using it at all"], ans: 2, why: "Helps: virtual walkthroughs give spatial sense that photos can't, saving time before in-person shortlisting. Limits: VR can't convey neighbourhood feel, sunlight, smells, or hidden issues (water damage). Best use: pre-screen to shortlist, not replace the final visit.", bloom: "apply" },
    { q: "A history teacher in Tashkent wants students to \"visit\" Registan Square in Samarkand as it looked 500 years ago. Which tech fits?", opts: ["VR — a fully computer-generated historical environment students experience through a headset", "A regular PowerPoint presentation showing the students historical photos of Registan Square today", "A physical bus trip to Samarkand, ignoring the students' interest in the historical past version", "There is no technology that can show a historical version of a place — only books can do this"], ans: 0, why: "VR fits historical reconstructions perfectly: the student stands in a computer-generated 1490s Registan, walks around, sees architecture as it was. This is impossible with photos (present only) or a bus trip (present only). VR shines where the target doesn't exist today.", bloom: "apply" },
    { q: "Users report motion sickness after 20 minutes of VR. Analyse the likely causes.", opts: ["VR is always broken in some way, so motion sickness is unavoidable no matter what you do", "Sensory conflict: low frame rate, artificial locomotion, and latency between head motion and scene update", "The user is physically weak and should train harder before using any VR headset at all", "VR never actually causes motion sickness — users imagine it and it is not a real physiological effect and most modern teams have moved to exactly this way of doing things"], ans: 1, why: "Causes: (a) low frame rate — the display lags head motion, mismatching eyes and inner ear. (b) Artificial locomotion (joystick walking) while the body is still — classic simulator sickness. (c) Head-to-scene latency. Fixes: 90+ fps, teleport locomotion, lower latency, breaks every 20 min.", bloom: "analyze" },
    { q: "A school considers replacing every field trip with VR field trips \"to save budget.\" Evaluate the idea.", opts: ["Always replace with VR — it is cheaper and fully equal to any real-world field trip experience", "Never use VR in schools — only physical field trips teach students anything real or valuable", "Budget is all that matters, so every decision should be made purely on cost savings alone", "Partly valuable — add VR for unreachable places, but don't replace real social group learning"], ans: 3, why: "VR can visit places you otherwise can't (Mars, inside a volcano, a historical site at a specific moment). BUT social experience, chaperoned peer learning, and real problem-solving don't transfer. Best fit: VR ADDS to field trips, not replaces them. Full replacement trades one learning mode for another — not an upgrade.", bloom: "evaluate" },
    { q: "Design a 45-minute VR lesson teaching 12-year-olds about the Roman Forum. What would they see, do, and leave with?", opts: ["Just play a regular history video inside the headset — no interaction or any real VR design at all and most modern teams have moved to exactly this way of doing things", "Let students walk around VR randomly for 45 minutes with no structure or any form of assessment", "Do not use VR — give a normal classroom lecture on the Roman Forum with printed textbook pages", "Structured lesson: open scene → explore hotspots → interact (mock Senate) → reflect with journal photo"], ans: 3, why: "Open: stand in the modern ruin, overlaid reconstruction appears. Explore: walk through key buildings, click hotspots (Senate, Temple of Saturn, Rostra). Interact: mock Senate vote. Checkpoint: in-scene quiz. Reflect: journal photo back in class. Outcome: spatial memory + engagement textbooks can't give, with structured assessment built in.", bloom: "create" },
  ],

  // ─── Topic 7: Augmented Reality ───
  7: [
    { q: "Which statement correctly distinguishes AR from VR?", opts: ["VR and AR are exactly the same technology, just sold under two different brand marketing names and most modern teams have moved to exactly this way of doing things", "VR fully replaces reality with a virtual world; AR overlays digital elements onto the real world", "AR is only for video games and never has any other use in any industry or educational setting", "VR is always cheaper than AR because AR hardware is much more expensive in every single case"], ans: 1, why: "VR replaces the real world entirely (headset blocks reality). AR overlays digital elements onto the real world (phone camera or clear glasses — reality still visible). Same underlying tech (3D, tracking) but opposite relationship with the real world.", bloom: "remember" },
    { q: "Which of these is the most common example of AR used by ordinary people today?", opts: ["Instagram and Snapchat face filters that add digital effects to the live camera view in real time", "A VR headset used to play immersive shooter games in a player's home living room after work", "A regular paper book read silently by a student at a desk with no digital devices involved at all", "An email application running on a laptop with no special hardware or camera-based features added"], ans: 0, why: "AR = digital content overlaid on the real world. Instagram, Snapchat, and TikTok filters add digital hats, masks, and effects onto your live camera view — that is AR, used by hundreds of millions daily. Other examples: IKEA Place, Pokémon GO, Google Lens.", bloom: "remember" },
    { q: "Why is AR typically more practical than VR for everyday tasks like navigation or shopping?", opts: ["AR is always cheaper than VR for every single user, no matter what device or app they use today", "VR hardware simply does not work well, while AR hardware is always perfectly reliable and ready", "AR keeps you aware of the real world, so you can still walk, look around, and interact safely", "AR and VR are identical in practical use — there is no real meaningful difference between them"], ans: 2, why: "AR keeps you aware of the real environment — you walk a street with directions overlaid, or place virtual furniture in YOUR room. VR isolates you, which is great for full immersion but bad for tasks tied to real locations and objects. VR's strength becomes a weakness outside entertainment.", bloom: "understand" },
    { q: "How does an AR app like IKEA Place know where to put the virtual sofa in your room?", opts: ["It uses the phone's camera and motion sensors to detect flat surfaces and scale the object correctly", "It randomly guesses where the sofa should sit, and the user must move it manually every single time and most modern teams have moved to exactly this way of doing things", "It connects to a database of every single home in the world and looks up that user's room layout", "It asks the user to manually type in the room's exact dimensions before showing any virtual object"], ans: 0, why: "AR apps use the camera + motion sensors (gyroscope, accelerometer) to understand depth, detect flat surfaces (floor, table), and anchor virtual objects with correct scale. The more features it sees (edges, textures, lighting), the better the tracking. This is why AR works worse on blank white walls.", bloom: "understand" },
    { q: "IKEA's app lets you place a virtual sofa in your living room via phone camera. Which tech, and what problem does it solve?", opts: ["VR — it fully blocks your view of the room and shows a completely different virtual environment", "AR — it overlays a 3D sofa on the live camera feed so you can preview fit, scale, and colour", "Blockchain — it securely records the sofa purchase on a public, decentralised, immutable ledger", "This is not a real application and no such technology has ever been built for any IKEA customer"], ans: 1, why: "AR overlays a 3D sofa onto the live camera feed. Problem solved: \"will this fit and look right in my room?\" — previously required guessing or measuring; now previewed in seconds with accurate scale. The real-world anchor IS the user's room.", bloom: "apply" },
    { q: "A surgeon uses AR glasses to see patient imaging (MRI, CT) overlaid on the operating site. Why AR (not VR) is correct here.", opts: ["VR would be a better choice because VR always gives a much clearer and sharper medical image", "The surgeon must see the real patient — AR adds info while keeping reality fully visible", "AR is really only useful for arcade video games and has no real application in surgical medicine", "Neither AR nor VR is useful in surgery — doctors should rely only on printed medical imaging films"], ans: 1, why: "A view of the actual patient is non-negotiable. AR adds info (MRI aligned to anatomy) without blocking the real site. VR would literally blind the surgeon. Reality-critical tasks NEED reality visible — AR is the only fit.", bloom: "apply" },
    { q: "A Tashkent tourism app wants visitors to point their phones at Registan Square and see facts appear over each building. Which tech?", opts: ["VR — every tourist must wear a full headset that completely hides the real square from view", "AR — digital facts overlay on the live camera feed while the real square stays fully visible", "Blockchain — the facts about each building are stored on an immutable decentralised public ledger", "No technology fits this need — tourists must rely on printed paper guidebooks and human guides"], ans: 1, why: "AR overlays digital labels, facts, and 3D models onto the live camera view of a real place. The tourist still sees Registan; the app adds a name, date, story over each building. This is one of AR's strongest use cases — tourism, museums, guided education.", bloom: "apply" },
    { q: "An AR museum guide overlays labels on paintings via phone. Users complain labels jitter and misalign. Analyse the causes.", opts: ["Users are imagining the problem; AR has no tracking issues and labels are always perfectly placed and most modern teams have moved to exactly this way of doing things", "Tracking loses anchors when the phone moves fast, lighting changes, or markers aren't clearly visible", "AR is always fundamentally jittery — this is an unfixable limitation of every AR system ever made", "The phone hardware is broken and must be replaced — it is never a software or environment issue"], ans: 1, why: "Causes: (a) tracking loses the painting when the phone moves fast — AR needs visual anchors. (b) Lighting changes (glare, shadow) confuse recognition. (c) Indoor GPS is imprecise — can't anchor alone. Fixes: clearer markers on paintings, improved tracking model, fallback to QR-scan if tracking fails.", bloom: "analyze" },
    { q: "A startup proposes AR glasses that show names and notes over every person you meet. Evaluate the product.", opts: ["Brilliant idea — every company should immediately build these glasses and ship them worldwide", "Flawed — facial recognition on strangers raises serious legal, consent, and trust problems", "Impossible — the technology needed for AR face recognition simply does not exist anywhere yet", "Every new tech product should be built regardless of privacy, consent, or legal considerations"], ans: 1, why: "Technically possible, socially and legally fraught. (1) Facial recognition on strangers is illegal in many regions. (2) The scanned person never consented. (3) Trust: would people tolerate AR-wearers at their events? (4) Hallucinated \"facts\" about strangers cause serious harm. The tech can work; the product likely can't ship in most markets.", bloom: "evaluate" },
    { q: "Design an AR learning app for Tashkent medical students practising anatomy. What do they see, do, and learn?", opts: ["Only a VR room with no physical objects at all — students sit alone and study without classmates", "Just show a regular PDF anatomy textbook floating in AR — nothing interactive, just a static page", "No technology at all — the students should memorise anatomy purely from printed paper textbook pages", "Layered 3D anatomy overlay on a shared physical space — peel skin → muscle → organs, quiz, discuss"], ans: 3, why: "Students wear AR glasses, look at a mannequin or empty table. Overlay: real-scale 3D body. Peel layers (skin → muscle → organs → bones), rotate, self-quiz by tapping structures. Instructor highlights parts for the class. Students still see each other, discuss, gesture — the social + spatial learning VR would isolate.", bloom: "create" },
  ],

  // ─── Topic 8: Internet of Things (IoT) ───
  8: [
    { q: "Which of the following best defines an IoT device?", opts: ["Any electrical device that is plugged into a wall socket and gets power from the mains supply", "A new kind of internet router used in homes and offices to connect laptops, phones, and printers and most modern teams have moved to exactly this way of doing things", "Any computer or smartphone that has a colour screen and runs modern mobile operating systems", "A physical object with sensors, processing, and network connectivity that shares data with other systems"], ans: 3, why: "IoT requires all three: sensing (or actuating), processing, and connectivity — so it can exchange data with other systems. A plain lamp is not IoT; a lamp with a temperature sensor that reports to an app is.", bloom: "remember" },
    { q: "Which of these is an example of an IoT device?", opts: ["A smart thermostat that reads room temperature and adjusts heating based on a phone-app schedule", "A regular paper notebook with nothing but handwritten class notes in ordinary blue or black ink", "An ordinary wall clock with two analogue hands that shows the time in the university lecture room", "A basic table lamp that is plugged into the wall and controlled only by the built-in manual switch"], ans: 0, why: "A smart thermostat senses temperature, processes data, connects to the network, and acts (adjusts heating). All three IoT pillars + an action. A paper notebook, an analogue clock, or a basic lamp have no sensing or connectivity — not IoT.", bloom: "remember" },
    { q: "Why is the IoT pipeline commonly described as Collect → Connect → Process → Act?", opts: ["The letters were chosen by coincidence and do not reflect any real structure inside IoT systems", "The order does not actually matter in practice, since the four steps can happen in any sequence", "IoT is really a single combined step, and breaking it into four parts is just an educational trick", "Those are the four distinct sequential stages of every IoT system — skipping any stage breaks it"], ans: 3, why: "Sensors collect data; connectivity sends it; a processor (edge or cloud) analyses it; an action follows (notification, actuator change, stored record). Skipping any stage breaks the system. Collecting without connectivity is isolated; processing without acting is just reporting.", bloom: "understand" },
    { q: "In an IoT system, what does the \"Act\" step usually do?", opts: ["The system shuts itself down once each stage is complete and waits for a human user to restart it", "The system does something useful — turn on a motor, send an alert, adjust a setting, log a record", "The system physically moves itself to a new location once it finishes processing all the sensor data", "Nothing happens — data just sits on the server forever and is never used for any real outcome at all"], ans: 1, why: "The \"Act\" step closes the loop by doing something useful: turn heating on, send a notification, adjust a motor, store a record. Without action, the pipeline is just collecting data. The value of IoT is in timely action based on sensed reality.", bloom: "understand" },
    { q: "A smart thermostat adjusts heating based on whether anyone is home. Map its behaviour to the IoT pipeline.", opts: ["The whole system is really one combined step and cannot be broken into any separate IoT stages", "There is no IoT involved at all — thermostats are not considered IoT devices in any modern system", "Motion + temperature sensors → cloud → decide based on rules → actuate the heating on or off", "Thermostats are old technology and don't fit the IoT pipeline even though they behave similarly"], ans: 2, why: "Collect: motion + temperature sensors. Connect: sends data to a home cloud. Process: an algorithm decides whether heating should run. Act: actuator turns heating on or off. A clean 4-step IoT loop — the same pipeline underlies every IoT system.", bloom: "apply" },
    { q: "An Uzbek farmer wants IoT for precision irrigation of cotton fields. Apply the pipeline — what sensors, processing, action?", opts: ["No sensors or processing needed — just water every field normally and ignore soil or weather data", "Buy many more tractors and hire more workers instead of using IoT or any smart irrigation system", "Soil moisture + weather sensors → farm server → compare to crop threshold → open or close valves", "IoT does not work in Uzbek farming — the climate and soil conditions make every sensor unreliable"], ans: 2, why: "Collect: soil-moisture sensors per section + weather station + satellite imagery. Connect: LoRa or cellular to a farm server. Process: compare moisture vs. crop threshold, factor in forecast. Act: open / close valves per section; log for later. Outcome: water only where needed, saving cost and yield.", bloom: "apply" },
    { q: "A Tashkent supermarket wants to know in real time which shelves are low on stock. Which IoT setup fits?", opts: ["Install one shared camera on the ceiling and hope a manager will notice every empty shelf on time", "Ignore IoT completely — just rely on the cashier counting the items sold and estimating shelves", "Ask every single customer to report empty shelves manually using a printed paper form at the door", "Weight sensors on each shelf → local server → alert when weight drops → staff refills that shelf"], ans: 3, why: "Weight or infrared sensors on each shelf detect stock drop → local gateway → cloud logs → alert to staff phone / display when a shelf falls below threshold. Clean IoT pipeline + real operational value. The alternatives rely on human observation, which is slow and error-prone.", bloom: "apply" },
    { q: "A factory deploys 10,000 IoT sensors. Six months later, they are a security nightmare. Analyse the root causes.", opts: ["IoT is always insecure in every case — there is nothing any engineer can ever do about this at all", "10,000 sensors is simply too many; any factory using more than 1,000 will always face this same issue and most modern teams have moved to exactly this way of doing things", "Default passwords left in place, no firmware update path, flat network, unencrypted traffic, no monitoring", "Only cloud-based IoT fails this way; on-premise IoT systems are always perfectly secure by default"], ans: 2, why: "Common causes: default passwords never changed, no firmware update mechanism (vulnerabilities compound), flat network (one device compromised = all reachable), unencrypted data, no monitoring for abnormal traffic. Fix: password rotation, OTA updates, segmentation, encryption, anomaly detection.", bloom: "analyze" },
    { q: "A Tashkent parent considers putting IoT cameras in every room of the house \"for safety.\" Evaluate the idea.", opts: ["Always install as many cameras as possible — privacy is less important than safety in every case", "Never install a single camera anywhere under any circumstances, even near the front door at night and most modern teams have moved to exactly this way of doing things", "Cameras are always completely safe and never suffer any data breach or privacy leak ever at all", "Flawed — real safety benefits come with real privacy risks; cover entries only, avoid private rooms"], ans: 3, why: "Benefits (deterrence, monitoring) are real but cost: (a) camera makers can be breached, leaking home video; (b) family members' privacy; (c) false sense of security replacing better physical measures. Better: entry points only, no bedrooms / bathrooms, strong passwords, local-only recording if possible.", bloom: "evaluate" },
    { q: "Design an IoT-based smart classroom for a Tashkent school. Devices, data, actions — and what NOT to do?", opts: ["Install 100 cameras and microphones to monitor every single student's every moment during the day", "Do not use any IoT at all — traditional classrooms are always better than any smart classroom ever", "Track every individual student's exact location across the whole school all day using personal chips and most modern teams have moved to exactly this way of doing things", "Environmental sensors (CO2, temp, door) + projector control + opt-in attendance + clear privacy limits"], ans: 3, why: "Devices: air-quality (CO2), temperature / humidity, door sensor, projector control, smart lights, opt-in attendance via student ID tap. Data: CO2 to auto-ventilate, attendance summary, maintenance logs. Actions: auto-ventilate at CO2 threshold, pre-heat before class, alert on projector fault. DO NOT: track individual-student location or record audio — privacy cost outweighs any benefit.", bloom: "create" },
  ],

  // ─── Topic 9: Generative AI ───
  9: [
    { q: "Which statement best distinguishes Generative AI from traditional AI?", opts: ["They are synonyms — both terms mean exactly the same thing and are used interchangeably by experts", "Traditional AI classifies or predicts from existing data; Generative AI creates new content", "Generative AI is always slower than any traditional AI system, no matter how much data they use", "Generative AI only works with text and cannot handle images, audio, video, or computer code at all"], ans: 1, why: "Traditional AI classifies, predicts, or recommends from existing data. Generative AI CREATES new content (text, images, audio, video, code) that didn't exist before, based on patterns in training data. Classifying an email as spam is traditional; writing a new email is generative.", bloom: "remember" },
    { q: "Which of these is an example of Generative AI?", opts: ["ChatGPT writing a brand-new essay based on a short prompt entered by an Uzbek student at 2 a.m.", "Gmail's spam filter sorting an incoming email as either spam or not spam based on its past examples", "Netflix recommending a new show based on what a user has watched in the past few months of usage", "A basic calculator app on a phone that adds two numbers entered by the user during a math homework"], ans: 0, why: "ChatGPT creates NEW text that didn't exist. The spam filter and Netflix recommender classify or rank existing content — traditional AI. A calculator is pure rule-based software, not AI at all. Generative = creates; traditional = classifies or predicts.", bloom: "remember" },
    { q: "Why does ChatGPT sometimes produce confident-sounding false information (a \"hallucination\")?", opts: ["It is a random one-off bug that OpenAI engineers will fix in the next software update soon", "Large language models always tell the truth by design — hallucinations are a misunderstanding", "OpenAI engineers will soon fix this permanently in the next major ChatGPT version this year", "LLMs optimise for the most plausible next word, not for truth, so fluent lies are a feature"], ans: 3, why: "LLMs generate the statistically most likely next token given the context. When asked about obscure or post-training facts, the model produces confident text that matches the PATTERN of truth without any truth-checking mechanism. Confidence is a property of fluent language, not verified knowledge. Hallucination is a feature of the generation process, not a bug.", bloom: "understand" },
    { q: "What does the letters \"LLM\" stand for, in the context of ChatGPT and similar tools?", opts: ["Large Language Model — a big AI trained on enormous amounts of text to predict likely next words", "Logical Learning Machine — a traditional rule-based AI system that uses if-then logical statements", "Live Language Manager — a piece of software used by translators to manage translation files daily", "Low-Level Memory — a type of computer memory hardware used in some modern gaming laptops today"], ans: 0, why: "LLM = Large Language Model. \"Large\" because trained on huge text datasets with billions of parameters. \"Language\" because it processes text. \"Model\" because it is a statistical pattern matcher predicting likely next words. ChatGPT, Claude, Gemini, and Yandex GPT are all LLMs.", bloom: "understand" },
    { q: "A student is writing an essay on WWII. Apply what you know about Generative AI — how should they use it?", opts: ["Have ChatGPT write the entire essay and submit it directly without any edits or changes at all", "Use AI as a research partner — brainstorm, explain, outline — then write and fact-check yourself", "Never use AI at all under any circumstances, even just to explain a confusing historical concept", "Have AI write the essay and then paraphrase about 20% of it to make it seem more like your own work"], ans: 1, why: "Use ChatGPT to brainstorm angles, explain confusing concepts, draft outlines, suggest counter-arguments. Then YOU write the essay in your own voice, fact-check every claim against reliable sources, and disclose AI assistance. Paraphrasing AI output is still plagiarism — the ideas and structure aren't yours.", bloom: "apply" },
    { q: "You ask an image generator for \"a photo of a cat.\" It produces a cat with six legs. Why does this happen?", opts: ["The model is completely broken and should never be trusted for any task involving image generation", "The model matches visual appearance patterns (fur, ears, whiskers) but does not model real anatomy", "It is a prank the developers put into the app deliberately to confuse first-time users of the tool", "The model sees everything perfectly and always produces anatomically perfect images of every subject"], ans: 1, why: "Image models learn pixel patterns associated with \"cat\" — fur, ears, eyes, whiskers — but they don't model anatomy. They produce plausible-LOOKING images without a concept of \"correct number of legs.\" Unusual poses or occlusion amplify this. Always verify physical / anatomical correctness before using AI-generated images.", bloom: "apply" },
    { q: "A Tashkent student uses ChatGPT in English but English is a second language. What is the ethical boundary for language polishing?", opts: ["Let AI fully rewrite every paragraph in perfect English — it is the same as using a spell-checker tool", "Use AI to fix grammar and suggest clearer phrasing, then YOU rewrite in your own voice; disclose use", "Never use AI for language help under any circumstances — students must only write with no tools at all", "Submit a first AI draft, then rename the file so it looks as if no AI was ever used on the document"], ans: 1, why: "Using AI for grammar / clarity suggestions is similar to a spell-checker or tutor — fine. But letting AI fully rewrite your argument removes YOUR voice and reasoning. Healthy middle: ask AI to flag unclear sentences; you rewrite in your own words; disclose the help. Assessment tests YOUR thinking, not AI's phrasing.", bloom: "apply" },
    { q: "A company uses Generative AI to write 10,000 product descriptions. Six months later, organic search traffic drops. Analyse likely causes.", opts: ["Google secretly hates AI-generated content and penalises every company that uses any AI at all", "Generic copy, search-engine detection of low-effort AI output, and duplicate-content patterns across items", "AI never works for SEO under any condition — only human writers ever produce content that ranks online and most modern teams have moved to exactly this way of doing things", "Organic traffic is completely random and has nothing to do with any content decision a business makes"], ans: 1, why: "Causes: (a) AI text is often generic, missing specific keywords real shoppers search. (b) Search engines increasingly detect and de-rank low-effort AI content. (c) Similar phrasing across items triggers duplicate-content penalties. (d) No brand voice = low dwell time. Fix: AI for first draft, human editor adds specifics and voice, unique per-product details.", bloom: "analyze" },
    { q: "A teacher argues: \"Generative AI will replace human writing. Students shouldn't bother learning to write anymore.\" Evaluate the claim.", opts: ["Correct — writing as a human skill is now fully obsolete and should be dropped from schools entirely", "Correct — AI is always better than humans at every type of writing across every single subject area today", "Writing is obsolete — universities should stop teaching it and spend the time on other modern subjects", "Flawed — writing IS thinking; AI-literate humans who can write AND use AI outperform either alone"], ans: 3, why: "(1) Writing IS thinking — composing clarifies ideas; AI skips that mental work. (2) AI remixes training patterns; genuinely original argument still needs a human. (3) Professional contexts (legal, medical, academic) require human accountability. (4) AI-literate humans who can write AND use AI outperform both AI-only and human-only on real tasks. Teaching writing is MORE important, not less.", bloom: "evaluate" },
    { q: "Design a policy for your class on how students may use Generative AI.", opts: ["Ban every use of AI completely and punish any student who admits to using any AI tool at any time", "Allow any and every use of AI with no rules at all and no disclosure required in any assignment", "Don't write a policy — let students decide individually what counts as fair use of AI tools for work", "Nuanced: allowed for brainstorming and polishing with disclosure; banned on timed tests; oral checks"], ans: 3, why: "Allowed: brainstorming, concept explanation, code review, outlines, language polishing for non-native English speakers. Required: disclose any AI use in an appendix (tool, prompt, what you changed). Not allowed: submitting AI output unedited; using AI on in-class timed assessments. Oral follow-ups verify understanding. AI literacy is a real skill; academic integrity is a real requirement.", bloom: "create" },
  ],

  // ─── Topic 10: AI Ethics (Bias, Plagiarism, Deepfakes, Privacy) ───
  10: [
    { q: "Which of the following is the correct definition of an AI \"hallucination\"?", opts: ["A confident-sounding factual fabrication — the AI states something false as if it were true fact", "The AI's hardware physically overheats and starts showing strange characters on the laptop screen", "The user imagines a wrong output — the AI was actually correct and the user misunderstood it fully", "A technical error that completely stops the AI system from responding to any further user input"], ans: 0, why: "The model generates confident-sounding content that is factually wrong or fabricated — often in specific details (dates, citations, quotes) while sounding authoritative. The key danger is confidence: the AI doesn't signal uncertainty.", bloom: "remember" },
    { q: "What is a \"deepfake\"?", opts: ["A synthetic video or audio of a real person saying or doing things they never actually said or did", "A deeply hidden file on a computer that even security experts have trouble finding on the hard drive", "A very long fake internet article written by a human journalist to deceive readers about a real event", "An old-school movie special effect used before computers — involving only costumes and stage makeup"], ans: 0, why: "A deepfake is AI-generated synthetic media (video, audio, image) that shows a real person saying or doing something they didn't. Used for entertainment (harmless parody), fraud (cloned CEO voice asking for money transfer), or defamation. The danger: visual / audio evidence is no longer automatically trustworthy.", bloom: "remember" },
    { q: "Why does AI bias exist even when developers don't intentionally program it into the system?", opts: ["Every AI developer in the world is secretly biased against specific groups of users on purpose", "Bias is only a marketing myth invented by journalists — real AI systems are completely objective", "All modern AI systems are perfectly unbiased by default, regardless of the data they were trained on", "Models learn patterns from biased historical data and replicate those patterns in future predictions"], ans: 3, why: "AI learns patterns from training data. If historical data reflects human bias (e.g., past hiring favoured one demographic), the model learns and replicates that pattern. The bias originates in the data, not the code — which makes it harder to detect and fix. Fixing it requires auditing data and choosing fairness constraints, not just writing more code.", bloom: "understand" },
    { q: "Why is using AI content without disclosure usually considered plagiarism?", opts: ["Because AI output is always copyrighted by OpenAI and using it is a direct copyright infringement", "Because passing off text or ideas you did not produce as your own work misleads about authorship", "Because AI text always contains hidden watermarks that every professor can automatically see instantly", "Because modern plagiarism detectors always catch AI use with 100% accuracy in every single case"], ans: 1, why: "Plagiarism is passing off someone else's (or something else's) work as your own. When you submit AI-generated text as if you wrote it, you misrepresent authorship — the assessment tests YOUR thinking, not the AI's. Disclosure (\"I used ChatGPT to brainstorm / polish\") turns it into assisted work, which is often allowed under clear rules.", bloom: "understand" },
    { q: "A student uses ChatGPT to explain a concept, then writes their essay in their own words based on that understanding. Another copies ChatGPT's output directly. Which is ethical?", opts: ["Both are plagiarism because any contact with AI automatically disqualifies a student's academic work and most modern teams have moved to exactly this way of doing things", "Student 2 is fine as long as they paraphrase 20% of the AI output to change some surface wording", "Both are fine — every student should use AI in every assignment without disclosing the use to anyone", "Student 1 — used AI as a learning tool; Student 2 submitted AI's work as their own, which is plagiarism"], ans: 3, why: "Student 1 used AI as a LEARNING TOOL — ethical, similar to using a tutor. Student 2 submitted AI's work as their own — plagiarism. The test: did YOU produce the ideas and the language, or did the AI? The line is about who did the thinking, not how much paraphrasing was applied.", bloom: "apply" },
    { q: "A Tashkent student wants to share personal health problems with an AI chatbot for advice. Apply privacy thinking — what should they consider?", opts: ["Share absolutely everything freely — AI chatbots are always fully private in every country and context", "Only ever share information with doctors, never with any AI chatbot under any circumstances at all", "AI chatbots always keep everything perfectly confidential and never store or use any user conversation", "Assume anything typed may be read, stored, or leaked — adjust what you share to that risk"], ans: 3, why: "(1) Where does the data go? Most chatbots log conversations for training. (2) Who can access logs? Employees, potentially legal subpoena. (3) Would you be comfortable if this conversation were public? If not, don't type it. (4) Alternatives: local LLMs, telemedicine with privacy guarantees, anonymised phrasing. The convenience of typing anything is deceptive; the audit trail is long.", bloom: "apply" },
    { q: "A Tashkent student sees a deepfake video of a local politician online. Apply critical thinking — what should they do before sharing?", opts: ["Share it immediately on every platform because viral content always improves a student's online reputation", "Verify through multiple independent news sources, check official channels, and consider who benefits", "Never share anything political online under any circumstances, even verified news from official channels", "Assume every political video is automatically a deepfake and dismiss it without checking any sources at all"], ans: 1, why: "Deepfakes are made to spread and manipulate opinion. Before sharing: (1) Check multiple independent news sources. (2) Look for the clip on the official channel of the person shown. (3) Ask who benefits from spreading this. (4) Reverse-image-search key frames. (5) Note inconsistencies (mouth sync, odd shadows). Sharing unverified video is how misinformation reaches millions.", bloom: "apply" },
    { q: "A hiring AI denies a disproportionate number of applicants from a specific neighbourhood. The AI was trained on historical hiring decisions. What went wrong?", opts: ["This is just random chance — the uneven pattern will naturally disappear on its own over the next year and most modern teams have moved to exactly this way of doing things", "The company should simply pick a different AI vendor and the problem will be solved immediately", "AI cannot be biased under any condition; the applicants are probably just less qualified on average", "Historical bias in training data leaks in through correlated features like zip code, even without demographics"], ans: 3, why: "If past hiring under-represented that neighbourhood, the model learned \"that zip = low fit.\" Correlated features (postcode) can smuggle demographic bias even when demographics are removed. Fixes: audit training data for past bias, remove or correct zip-code correlations, test model outputs across groups, require human review on high-stakes decisions, apply fairness constraints during training.", bloom: "analyze" },
    { q: "A company makes deepfake videos of competitors' CEOs saying false things. Evaluate the ethical and legal dimensions.", opts: ["It is fine under free speech — companies should be allowed to create any video of any person at all", "Always acceptable because it is technically just software; no speech laws apply to AI-generated content", "Only illegal in certain countries — it is a grey area and most companies can safely do this worldwide", "Flawed — defamation, fraud, reputational harm; erodes trust in all video evidence far beyond the target"], ans: 3, why: "(1) Legally: defamation, fraud, and specific deepfake laws in many jurisdictions. (2) Ethically: non-consensual portrayal, intent to deceive, reputational harm. (3) Practically: erodes trust in ALL video evidence, harming society beyond the target. Free speech protects opinion, not fabricated attribution. The company faces both lawsuits and social sanction.", bloom: "evaluate" },
    { q: "Design a personal AI-use ethics checklist you'd apply before using any AI tool for an important decision.", opts: ["Skip ethics entirely — just use AI freely and hope nothing goes wrong in any important situation", "Use AI freely for everything without any check at all — it never produces any harmful or wrong output and most modern teams have moved to exactly this way of doing things", "Never use AI for anything important under any circumstances, even when used with proper disclosure", "5-point check: output accuracy, data sensitivity, attribution / disclosure, bias risk, over-dependence"], ans: 3, why: "1. OUTPUT: could the result harm someone if wrong? Fact-check. 2. DATA: am I typing sensitive info? If yes, use a privacy-respecting alternative. 3. ATTRIBUTION: am I passing AI output off as my own work? Disclose. 4. BIAS: is this a decision where historical bias matters (hiring, lending, admissions)? Apply human review. 5. DEPENDENCE: am I outsourcing thinking I should own? AI augments, not replaces, judgment. Run the list in ~30 seconds before any serious use.", bloom: "create" },
  ],
};
